def ctry_qs(c):
    d=F[c]; out=[]
    others=lambda k:[F[x][k] for x in F if x!=c and F[x].get(k)]
    out.append((f"ما عاصمة {c}؟",o(d['cap'],[d['cap']]+others('cap')+["عمّان","القاهرة","بغداد","الرباط"])))
    out.append((f"ما عملة {c}؟",o(d['cur'],[d['cur'],"الدرهم","الجنيه","الدينار","الريال","الليرة","الشيكل"])))
    out.append((f"ما الطبق الشعبي الشهير في {c}؟",o(d['dish'],[d['dish']]+others('dish')+["المنسف","الكشري"])))
    out.append((f"على أي بحر أو خليج تطل {c}؟",o(d['sea'],["البحر الأحمر","الخليج العربي","بحر العرب","البحر المتوسط"])))
    allc=[x for k in F for x in F[k]['cities']]
    for city in d['cities']:
        out.append((f"مدينة «{city}» تقع في أي دولة؟",o(c,list(F))))
    for s in d['sites']:
        out.append((f"في أي دولة يقع معلم «{s}»؟",o(c,list(F))))
    out+=EXTRA[c]
    return out
